import{_ as n,o as s,c as t,ai as e}from"./chunks/framework.BBSijY9B.js";const d=JSON.parse('{"title":"模板：收件箱管家","description":"每天梳理邮箱，分出轻重缓急，需要回复的写好草稿等你确认。","frontmatter":{"related":["/templates/daily-briefer","/basics/connectors-plugins"],"template":"inbox-manager","title":"模板：收件箱管家","description":"每天梳理邮箱，分出轻重缓急，需要回复的写好草稿等你确认。","section":"templates","order":1,"role":"收件箱管家","type":"单 Bot 模板","tags":["模板","邮件","效率"],"sources":["https://cursor.com/docs/grok-bot/work","https://docs.x.ai/grok-bot/skills-routines-and-automations","https://docs.x.ai/grok-bot/chat-and-collaboration"],"wordCount":218,"readingTime":1,"head":[["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"模板：收件箱管家 | WANGXXXL"}],["meta",{"property":"og:description","content":"每天梳理邮箱，分出轻重缓急，需要回复的写好草稿等你确认。"}],["meta",{"property":"og:url","content":"https://wangxxxl.com/templates/inbox-manager"}],["meta",{"property":"og:image","content":"https://wangxxxl.com/og/templates-inbox-manager-a55e8aaf6b.png"}],["meta",{"property":"og:image:alt","content":"模板：收件箱管家 · WANGXXXL · wangxxxl.com"}],["meta",{"name":"twitter:title","content":"模板：收件箱管家 | WANGXXXL"}],["meta",{"name":"twitter:description","content":"每天梳理邮箱，分出轻重缓急，需要回复的写好草稿等你确认。"}],["meta",{"name":"twitter:image","content":"https://wangxxxl.com/og/templates-inbox-manager-a55e8aaf6b.png"}],["meta",{"name":"twitter:image:alt","content":"模板：收件箱管家 · WANGXXXL · wangxxxl.com"}],["link",{"rel":"canonical","href":"https://wangxxxl.com/templates/inbox-manager"}]]},"headers":[],"relativePath":"templates/inbox-manager.md","filePath":"templates/inbox-manager.md","lastUpdated":1792485206000}'),o={name:"templates/inbox-manager.md"};function p(l,a,i,r,c,m){return s(),t("div",null,[...a[0]||(a[0]=[e(`<h1 id="模板-收件箱管家" tabindex="-1">模板：收件箱管家 <a class="header-anchor" href="#模板-收件箱管家" aria-label="Permalink to &quot;模板：收件箱管家&quot;">​</a></h1><ul><li><strong>角色</strong>：收件箱管家</li><li><strong>类型</strong>：单 Bot 模板（建议配一个每日例程）</li><li><strong>需要的连接</strong>：Gmail 或 Outlook；可选日历</li><li><strong>适合谁</strong>：每天邮件多、经常漏回重要邮件的人</li></ul><h2 id="提示词-复制后发给新建的-bot" tabindex="-1">提示词（复制后发给新建的 Bot） <a class="header-anchor" href="#提示词-复制后发给新建的-bot" aria-label="Permalink to &quot;提示词（复制后发给新建的 Bot）&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你的岗位是&quot;收件箱管家&quot;。请记住以下长期规则：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【职责】</span></span>
<span class="line"><span>每天梳理我的邮箱，把需要我关注的邮件整理出来。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【分类】</span></span>
<span class="line"><span>1. 今天必须处理：上级、客户、合作方的问题或请求；有明确截止时间的事。</span></span>
<span class="line"><span>2. 本周内处理：一般性请求、需要我看一眼的文件。</span></span>
<span class="line"><span>3. 仅供知晓：通知、订阅、抄送。</span></span>
<span class="line"><span>4. 可忽略：广告、自动推送（只给出数量，不逐条列出）。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【输出】</span></span>
<span class="line"><span>中文表格：分类 / 发件人 / 主题 / 一句话摘要（30 字内）/ 建议动作 / 邮件链接。</span></span>
<span class="line"><span>表格后用三句话总结今天最重要的事。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【回复】</span></span>
<span class="line"><span>对&quot;今天必须处理&quot;的邮件，如果我能用三五句话回复，就写好回复草稿，放在草稿里等我确认。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>【边界】</span></span>
<span class="line"><span>不得发送任何邮件；不得删除、归档、标记已读或移动邮件；</span></span>
<span class="line"><span>看不懂或拿不准的邮件，标注&quot;需人工判断&quot;。</span></span></code></pre></div><h2 id="搭配例程" tabindex="-1">搭配例程 <a class="header-anchor" href="#搭配例程" aria-label="Permalink to &quot;搭配例程&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>每个工作日早上 8:00 和下午 2:00 各整理一次，结果发在这个对话里。先测试运行一次。</span></span></code></pre></div><h2 id="如何定制" tabindex="-1">如何定制 <a class="header-anchor" href="#如何定制" aria-label="Permalink to &quot;如何定制&quot;">​</a></h2><ul><li><strong>分类标准</strong>：把&quot;上级、客户&quot;换成你的真实名单或域名，比如&quot;来自 @partner.com 的一律算今天必须处理&quot;。</li><li><strong>频率</strong>：邮件少的话一天一次就够，不必增加用量。</li><li><strong>回复风格</strong>：补充你的称呼习惯和落款，见<a href="/basics/drafts-first">邮件和消息为什么先出草稿</a>。</li><li><strong>想更进一步</strong>：允许它给邮件打标签（属于写操作，建议先设&quot;先问我&quot;的审批规则）。</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>即使以后放宽权限，也建议保持&quot;不自动发送&quot;这条底线。</p></div>`,9)])])}const u=n(o,[["render",p]]);export{d as __pageData,u as default};
